/**
 * pdv-movimentacao — API HTTP de Movimentação de Caixas QR para PDV de Terceiros
 *
 * Expõe operações de consulta, entrada e saída de caixas (etiquetas QR) e
 * criação de requisições para PDVs externos.
 *
 * Auth: header x-api-key OU Authorization: Bearer <chave>, validado via RPC
 * validar_pdv_api_key (bcrypt, timing-safe, escopo por loja).
 * Sem JWT: verify_jwt = false no config.toml (auth é por API key própria).
 *
 * Endpoints:
 *   GET  /pdv-movimentacao/etiqueta/:uid  → consultar_etiqueta_pdv (R1/A1)
 *   POST /pdv-movimentacao/entrada        → movimentar_lote_pdv tipo=entrada (R2/A2)
 *   POST /pdv-movimentacao/saida          → movimentar_lote_pdv tipo=saida (R3/A3)
 *   POST /pdv-movimentacao/requisicao     → criar_requisicao_pdv (R4/A4)
 *
 * Spec: .harness/spec/pdv-recebimento-externo/spec.md
 * ADR:  .harness/memory-bank/decisions/ADR-20260625-pdv-movimentacao-externa.md
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

// ─── Constantes ──────────────────────────────────────────────────────────────

const MAX_UIDS_PER_REQUEST = 500

// DESVIO INTENCIONAL (F5): Access-Control-Allow-Origin: '*'
// Esta é uma API server-to-server para PDV parceiro externo.
// Restringir a um domínio Momma bloquearia o terceiro (que opera em domínio próprio).
// Segurança não depende de CORS — depende de x-api-key com bcrypt (RPC validar_pdv_api_key).
// Revisado e aceito pelo security-reviewer (PASS-WITH-WARNINGS, sem blocker).
const CORS_HEADERS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers':
    'authorization, x-client-info, apikey, content-type, x-api-key',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
}

const MAX_ITENS_REQUISICAO = 1000

// ─── Tipos ───────────────────────────────────────────────────────────────────

type BatchBodyOk = { ok: true; loja_id: number; uids: string[] }
type BatchBodyError = { ok: false; error: string; message: string; httpStatus: number }
type BatchBodyResult = BatchBodyOk | BatchBodyError

type RequisicaoItem = {
  /** Obrigatório quando produto_master_id ausente; opcional caso contrário. */
  nome_produto?: string
  quantidade: number
  /** Quando presente, a RPC resolve o nome canônico via produtos_master.nome (ativo=true). */
  produto_master_id?: number
  observacao?: string
}
type RequisicaoBodyOk = {
  ok: true
  loja_id: number
  itens: RequisicaoItem[]
  pedido_externo_id?: string
  data_recebimento?: string
  data_pedido?: string
  solicitante?: string
  subtitle?: string
}
type RequisicaoBodyError = { ok: false; error: string; message: string; httpStatus: number }
type RequisicaoBodyResult = RequisicaoBodyOk | RequisicaoBodyError

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Extrai a API key do request.
 * Aceita: `x-api-key: <chave>` OU `Authorization: Bearer <chave>`.
 * Exportada para testabilidade.
 */
export function extractApiKey(req: Request): string | null {
  const fromHeader = req.headers.get('x-api-key')
  if (fromHeader) return fromHeader

  const authHeader = req.headers.get('authorization') ?? req.headers.get('Authorization')
  if (authHeader?.startsWith('Bearer ')) return authHeader.slice(7)

  return null
}

/** Resposta JSON com headers CORS e Content-Type corretos. */
function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
  })
}

/**
 * Extrai rota e params do path após o nome da função.
 * Exemplo: /functions/v1/pdv-movimentacao/etiqueta/ABC → { route: 'etiqueta', params: ['ABC'] }
 * Exportada para testabilidade (testes sem rede).
 */
export function parseRoute(url: URL): { route: string; params: string[] } {
  const parts = url.pathname.split('/').filter(Boolean)
  const funcIdx = parts.findIndex((p) => p === 'pdv-movimentacao')
  const routeParts = funcIdx >= 0 ? parts.slice(funcIdx + 1) : []
  return {
    route: routeParts[0] ?? '',
    params: routeParts.slice(1),
  }
}

/**
 * Valida o body de uma requisição de entrada/saída.
 * Exportada para testabilidade (testes sem rede).
 */
export function validateBatchBody(body: unknown): BatchBodyResult {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return {
      ok: false,
      error: 'invalid_body',
      message: 'Corpo JSON deve ser um objeto com loja_id e uids',
      httpStatus: 400,
    }
  }

  const b = body as Record<string, unknown>

  if (typeof b.loja_id !== 'number' || !Number.isInteger(b.loja_id)) {
    return {
      ok: false,
      error: 'loja_id_required',
      message: 'loja_id é obrigatório e deve ser um número inteiro',
      httpStatus: 400,
    }
  }

  if (!Array.isArray(b.uids) || b.uids.length === 0) {
    return {
      ok: false,
      error: 'uids_required',
      message: 'uids deve ser um array não-vazio de strings (UIDs de etiquetas)',
      httpStatus: 400,
    }
  }

  if (b.uids.length > MAX_UIDS_PER_REQUEST) {
    return {
      ok: false,
      error: 'too_many_uids',
      message: `Máximo ${MAX_UIDS_PER_REQUEST} UIDs por requisição`,
      httpStatus: 422,
    }
  }

  // F4: valida que cada elemento é string não-vazia (rejeita null, number, etc.)
  if (!b.uids.every((u: unknown) => typeof u === 'string' && u.length > 0)) {
    return {
      ok: false,
      error: 'invalid_uid',
      message: 'Todos os UIDs devem ser strings não-vazias',
      httpStatus: 400,
    }
  }

  return {
    ok: true,
    loja_id: b.loja_id,
    uids: b.uids as string[],
  }
}

/**
 * Valida o body de POST /requisicao.
 * Exportada para testabilidade (testes sem rede).
 */
export function validateRequisicaoBody(body: unknown): RequisicaoBodyResult {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return {
      ok: false,
      error: 'invalid_body',
      message: 'Corpo JSON deve ser um objeto com loja_id e itens',
      httpStatus: 400,
    }
  }

  const b = body as Record<string, unknown>

  if (typeof b.loja_id !== 'number' || !Number.isInteger(b.loja_id)) {
    return {
      ok: false,
      error: 'loja_id_required',
      message: 'loja_id é obrigatório e deve ser um número inteiro',
      httpStatus: 400,
    }
  }

  if (!Array.isArray(b.itens) || b.itens.length === 0) {
    return {
      ok: false,
      error: 'itens_required',
      message: 'itens deve ser um array não-vazio',
      httpStatus: 400,
    }
  }

  if (b.itens.length > MAX_ITENS_REQUISICAO) {
    return {
      ok: false,
      error: 'too_many_itens',
      message: `Máximo ${MAX_ITENS_REQUISICAO} itens por requisição`,
      httpStatus: 422,
    }
  }

  // FIX E: validação de formato de data (YYYY-MM-DD) para campos opcionais
  const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/
  if (typeof b.data_recebimento === 'string' && !ISO_DATE.test(b.data_recebimento)) {
    return {
      ok: false,
      error: 'data_invalida',
      message: 'data_recebimento deve estar no formato YYYY-MM-DD',
      httpStatus: 400,
    }
  }
  if (typeof b.data_pedido === 'string' && !ISO_DATE.test(b.data_pedido)) {
    return {
      ok: false,
      error: 'data_invalida',
      message: 'data_pedido deve estar no formato YYYY-MM-DD',
      httpStatus: 400,
    }
  }

  // FIX E: caps de comprimento para campos de string opcionais (top-level)
  if (typeof b.pedido_externo_id === 'string' && b.pedido_externo_id.length > 128) {
    return {
      ok: false,
      error: 'campo_muito_longo',
      message: 'pedido_externo_id máximo 128 caracteres',
      httpStatus: 400,
    }
  }
  if (typeof b.solicitante === 'string' && b.solicitante.length > 100) {
    return {
      ok: false,
      error: 'campo_muito_longo',
      message: 'solicitante máximo 100 caracteres',
      httpStatus: 400,
    }
  }
  if (typeof b.subtitle === 'string' && b.subtitle.length > 300) {
    return {
      ok: false,
      error: 'campo_muito_longo',
      message: 'subtitle máximo 300 caracteres',
      httpStatus: 400,
    }
  }

  // Valida cada elemento.
  // Regra de identificação: produto_master_id (integer) OU nome_produto (string não-vazia).
  // Se nem um nem outro → 400 item_invalido.
  for (const item of b.itens) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      return {
        ok: false,
        error: 'item_invalido',
        message: 'Cada item deve ser um objeto com (produto_master_id ou nome_produto) e quantidade',
        httpStatus: 400,
      }
    }
    const it = item as Record<string, unknown>

    const hasPmid = typeof it.produto_master_id === 'number' && Number.isInteger(it.produto_master_id)
    const hasNome = typeof it.nome_produto === 'string' && it.nome_produto.trim().length > 0

    // FIX E: cap de comprimento no nome_produto (quando fornecido)
    if (hasNome && (it.nome_produto as string).length > 255) {
      return {
        ok: false,
        error: 'campo_muito_longo',
        message: 'nome_produto máximo 255 caracteres',
        httpStatus: 400,
      }
    }

    if (!hasPmid && !hasNome) {
      return {
        ok: false,
        error: 'item_invalido',
        message:
          'Cada item deve ter produto_master_id (integer) OU nome_produto (string não-vazia)',
        httpStatus: 400,
      }
    }

    if (typeof it.quantidade !== 'number' || it.quantidade <= 0) {
      const ref = hasPmid
        ? `produto_master_id=${it.produto_master_id as number}`
        : `"${it.nome_produto as string}"`
      return {
        ok: false,
        error: 'quantidade_invalida',
        message: `Item ${ref}: quantidade deve ser número > 0`,
        httpStatus: 400,
      }
    }
  }

  return {
    ok: true,
    loja_id: b.loja_id,
    itens: b.itens as RequisicaoItem[],
    pedido_externo_id: typeof b.pedido_externo_id === 'string' ? b.pedido_externo_id : undefined,
    data_recebimento: typeof b.data_recebimento === 'string' ? b.data_recebimento : undefined,
    data_pedido: typeof b.data_pedido === 'string' ? b.data_pedido : undefined,
    solicitante: typeof b.solicitante === 'string' ? b.solicitante : undefined,
    subtitle: typeof b.subtitle === 'string' ? b.subtitle : undefined,
  }
}

// ─── Handler principal (exportado para testes) ────────────────────────────────

/**
 * Handler desacoplado do serve() para permitir testes unitários sem rede.
 * O supabase client é injetado externamente (real ou mock).
 */
export async function handler(
  req: Request,
  // deno-lint-ignore no-explicit-any
  supabase: any,
): Promise<Response> {
  // ── Auth: x-api-key header OU Authorization: Bearer <chave> ──────────────
  const apiKey = extractApiKey(req)
  if (!apiKey) {
    return json(
      {
        error: 'missing_api_key',
        message: 'Autenticação obrigatória: header x-api-key ou Authorization: Bearer <chave>',
      },
      401,
    )
  }

  // ── Validar API key via RPC (bcrypt, timing-safe) ──────────────────────────
  const { data: valResult, error: valError } = await supabase.rpc(
    'validar_pdv_api_key',
    { p_key: apiKey },
  )

  if (valError || !valResult?.ok) {
    return json(
      { error: 'unauthorized', message: 'API key inválida, inativa ou revogada' },
      401,
    )
  }

  const apiKeyId: string = valResult.api_key_id
  const lojaIds: number[] = (valResult.loja_ids ?? []) as number[]

  // ── Roteamento ─────────────────────────────────────────────────────────────
  const url = new URL(req.url)
  const { route, params } = parseRoute(url)

  // GET /etiqueta/:uid ─────────────────────────────────────────────────────
  if (req.method === 'GET' && route === 'etiqueta') {
    const uid = params[0]
    if (!uid) {
      return json(
        { error: 'uid_required', message: 'UID obrigatório no path: /etiqueta/{uid}' },
        400,
      )
    }

    const { data, error } = await supabase.rpc('consultar_etiqueta_pdv', {
      p_uid: uid,
    })

    if (error) {
      // F-04: não vazar internals ao parceiro; detalhe logado server-side
      console.error('[pdv-movimentacao] consultar_etiqueta_pdv error:', error.message)
      return json(
        { error: 'internal_error', message: 'Erro interno ao processar a requisição' },
        500,
      )
    }

    if (!data?.ok) {
      return json(
        { error: 'not_found', message: 'Etiqueta não encontrada', uid },
        404,
      )
    }

    return json(data)
  }

  // POST /entrada ou POST /saida ────────────────────────────────────────────
  if ((route === 'entrada' || route === 'saida') && req.method === 'POST') {
    // Parse body
    let body: unknown
    try {
      body = await req.json()
    } catch {
      return json(
        { error: 'invalid_json', message: 'Corpo deve ser JSON válido' },
        400,
      )
    }

    // Validar corpo
    const validated = validateBatchBody(body)
    if (!validated.ok) {
      return json(
        { error: validated.error, message: validated.message },
        validated.httpStatus,
      )
    }

    const { loja_id, uids } = validated

    // Validar escopo de loja (R6/A6)
    if (!lojaIds.includes(loja_id)) {
      return json(
        {
          error: 'loja_fora_escopo',
          message: `Loja ${loja_id} não está no escopo desta chave`,
          loja_ids_permitidos: lojaIds,
        },
        403,
      )
    }

    // Executar batch via RPC
    const { data, error } = await supabase.rpc('movimentar_lote_pdv', {
      p_loja_id: loja_id,
      p_uids: uids,
      p_tipo: route,         // 'entrada' | 'saida'
      p_api_key_id: apiKeyId,
    })

    if (error) {
      // F-04: não vazar internals ao parceiro; detalhe logado server-side
      console.error('[pdv-movimentacao] movimentar_lote_pdv error:', error.message)
      return json(
        { error: 'internal_error', message: 'Erro interno ao processar a requisição' },
        500,
      )
    }

    return json(data)
  }

  // POST /requisicao ────────────────────────────────────────────────────────
  if (route === 'requisicao' && req.method === 'POST') {
    let body: unknown
    try {
      body = await req.json()
    } catch {
      return json({ error: 'invalid_json', message: 'Corpo deve ser JSON válido' }, 400)
    }

    const validated = validateRequisicaoBody(body)
    if (!validated.ok) {
      return json({ error: validated.error, message: validated.message }, validated.httpStatus)
    }

    // Validar escopo de loja antes de chamar RPC
    if (!lojaIds.includes(validated.loja_id)) {
      return json(
        {
          error: 'loja_fora_escopo',
          message: `Loja ${validated.loja_id} não está no escopo desta chave`,
          loja_ids_permitidos: lojaIds,
        },
        403,
      )
    }

    // Montar payload para a RPC (inclui apenas campos presentes)
    const payload: Record<string, unknown> = {
      itens: validated.itens,
    }
    if (validated.pedido_externo_id !== undefined) payload.pedido_externo_id = validated.pedido_externo_id
    if (validated.data_recebimento !== undefined) payload.data_recebimento = validated.data_recebimento
    if (validated.data_pedido !== undefined) payload.data_pedido = validated.data_pedido
    if (validated.solicitante !== undefined) payload.solicitante = validated.solicitante
    if (validated.subtitle !== undefined) payload.subtitle = validated.subtitle

    const { data, error } = await supabase.rpc('criar_requisicao_pdv', {
      p_loja_id: validated.loja_id,
      p_api_key_id: apiKeyId,
      p_payload: payload,
    })

    if (error) {
      console.error('[pdv-movimentacao] criar_requisicao_pdv error:', error.message)
      return json(
        { error: 'internal_error', message: 'Erro interno ao processar a requisição' },
        500,
      )
    }

    // FIX D: mapear retorno da RPC por `codigo` estruturado (não string-match em `erro`)
    if (!data?.ok) {
      const codigoToStatus: Record<string, number> = {
        escopo: 403,
        loja_invalida: 422,
        itens_invalidos: 422,
        quantidade_invalida: 422,
        payload_invalido: 422,
      }
      const httpStatus =
        typeof data?.codigo === 'string' && data.codigo in codigoToStatus
          ? codigoToStatus[data.codigo]
          : 500  // codigo ausente ou desconhecido = erro inesperado do RPC
      return json(data, httpStatus)
    }

    return json(data) // 200: { ok: true, requisicao_id, ... } ou { ok: true, duplicado: true, ... }
  }

  // Rota não encontrada
  return json(
    {
      error: 'not_found',
      message: `Rota não encontrada: ${req.method} ${url.pathname}`,
      rotas_validas: [
        'GET  /pdv-movimentacao/etiqueta/:uid',
        'POST /pdv-movimentacao/entrada',
        'POST /pdv-movimentacao/saida',
        'POST /pdv-movimentacao/requisicao',
      ],
    },
    404,
  )
}

// ─── Bootstrap ───────────────────────────────────────────────────────────────

const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? ''
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''

serve(async (req: Request) => {
  // OPTIONS pre-flight (CORS)
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: CORS_HEADERS })
  }

  // Service role client — bypassa RLS (segurança via RPC SECURITY DEFINER)
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)

  return handler(req, supabase)
})
